import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        sets = []
        for i in range(n):
            k = int(next(iterator))
            current_set = []
            for _ in range(k):
                current_set.append(int(next(iterator)))
            sets.append(current_set)

        value_to_indices = {}
        found_pair = None

        for idx, s in enumerate(sets):
            s_idx = idx + 1
            for val in s:
                if val in value_to_indices:
                    for prev_idx in value_to_indices[val]:
                        if found_pair is None:
                            pass
                        else:
                            break
                    value_to_indices[val].append(s_idx)
                else:
                    value_to_indices[val] = [s_idx]

        pair_found = False
        ans_a, ans_b = -1, -1

        for val, indices in value_to_indices.items():
            if len(indices) >= 2:
                if len(indices) > 2:
                    ans_a, ans_b = indices[0], indices[1]
                    pair_found = True
                    break
                else:
                    pass

        if not pair_found:
            count_map = {}
            for idx, s in enumerate(sets):
                s_idx = idx + 1
                for val in s:
                    if val not in count_map:
                        count_map[val] = []
                    count_map[val].append(s_idx)

            for val, indices in count_map.items():
                if len(indices) >= 2:
                    ans_a, ans_b = indices[0], min(indices)
                    if ans_a != ans_b:
                        pair_found = True
                        break
                    else:
                        if len(indices) > 1:
                            ans_a, ans_b = indices[0], indices[1]
                            pair_found = True
                            break

        if not pair_found:
            intersections = {}
            for idx, s in enumerate(sets):
                for i in range(len(s)):
                    for j in range(i + 1, len(s)):
                        u, v = sorted((s[i], s[j]))
                        key = (u, v)
                        if key in intersections:
                            prev_idx = intersections[key]
                            ans_a, ans_b = prev_idx, idx + 1
                            pair_found = True
                            break
                        else:
                            intersections[key] = idx + 1
                    if pair_found:
                        break
                if pair_found:
                    break

        if pair_found:
            results.append(f"{ans_a} {ans_b}")
        else:
            results.append("-1")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
